// wrapper takes 100% of the flex row, collapsing siblings
wrapper.style.cssText = 'display:flex;flex-direction:row;width:100%;flex:1 1 100%;align-self:stretch;overflow:hidden;position:relative;';
// → wrapper 1891px, drama col 0px — episode selector gone

cases.good:
// detect flex-row parent with siblings, preserve original footprint
const parentCs = getComputedStyle(originalParent);
const hasFlexSiblings = parentCs.display === 'flex'
  && /row/.test(parentCs.flexDirection)
  && Array.from(originalParent.children).filter(c => c !== playerShell && c.getBoundingClientRect().width > 0).length > 0;
const wrapperFlex = hasFlexSiblings ? `0 0 ${Math.round(playerRect.width)}px` : '1 1 100%';
wrapper.style.cssText = `display:flex;flex-direction:row;flex:${wrapperFlex};height:${h};align-self:stretch;overflow:hidden;position:relative;`;
// → wrapper 1103px (video col), drama col 788px — episode selector visible

cases.bad:
// works by accident — sibling has fixed width, wrapper shrinks
wrapper.style.cssText = '...flex:1 1 100%;width:100%...';
// → wrapper 1226px (shrunk from 100%), resources 409px — works but fragile

cases.good:
// explicit — wrapper takes exactly the video column's width
const wrapperFlex = `0 0 ${Math.round(playerRect.width)}px`;
wrapper.style.cssText = `...flex:${wrapperFlex}...`;
// → wrapper 1226px, resources 409px — correct and robust
